// TH16 v1.00a Stage 7 Extra final boss, SPELL_ID 110.
// Source: st07bs.ecl.txt BossCard2 1198-1262 (+ BossCard2_at 1339-1352,
// BossCard2_at2 1354-1369, BossCard2_ECir00 1280-1304, BossCard2_ECir00_at 1306-1337).
// Rank 4 only; the source has no per-difficulty branch.

const TIME_LIMIT: int = 4324;
const OPENING_BUFFER: int = 120;
const SPELL_ID: int = 110;

// transcribe/th16/bullet-types.md: th16 type 8 / type 16
const TH16_RICE: int = 480;
const TH16_STAR_R: int = 608;

// src etEx(0,0,2097152,120,-999999,2.0,-999999): VELTIME, angle kept,
// scalar speed 1.0 -> 2.0 over 120 frames.
xformdef RING_SPEEDUP {
    step_speed(2fx, 120);
}

// ---- boss movement: src moveRand(60,4,1.0) under moveLimit(0,128,240,64) ----
// Recipe from transcribe/th16/movement.md (same limit as Stage01 BossCard2):
// logical unit vector in fx0/fx1, step index in int0, per-frame limit clamp.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60-k) as fx / 60; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

sub card_move_rand() {
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -60fx {
        a = r/3;
    } else if $self_x > 60fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; }
    } else {
        a = r/4;
        var choose: int = rand(65536)%3;
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

// Every source wait(n) of the boss task counts movement ticks.
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

// src BossCard2_at2 (1354-1369): 64-way ring, base = ANGLE_PLAYER read from the
// boss center at config time, port (0,-24), etDist 32 net of the ANIM -4*1.0.
sub fire_back_ring() {
    var base: angle = aim_player();
    sh_reset(1);
    sh_sprite(1, TH16_STAR_R, 4);
    sh_ring(1, 1);
    sh_count(1, 64, 1);
    sh_speed(1, 1fx, 0fx);
    sh_offset(1, 0fx, -24fx);
    sh_dist(1, 28fx);
    sh_angle(1, base, 0deg);
    sh_xform(1, RING_SPEEDUP);
    sh_fire(1);
}

// src BossCard2_at (1339-1352): 20 pairs every 30 frames, absolute spawns.
async sub ecir_wave() {
    for i in 0..20 {
        _ = spawn_enemy(-224fx, 448fx, 100, 0, 1000, 0, ecir(0));
        _ = spawn_enemy(224fx, 448fx, 100, 0, 1000, 0, ecir(1));
        wait(30);
    }
}

// src BossCard2_ECir00 (1280-1304). enmCreateA is mirror 0, enmCreateAM mirror 1;
// the M child's angles are the horizontal mirror of the plain one.
async sub ecir(mirror: int) {
    set_invuln(65535);
    set_hurtbox(12fx);
    set_hitbox(8fx);
    var a0: angle = 0deg;
    var a2: angle = 180deg;
    if mirror != 0 { a0 = 180deg; a2 = 0deg; }
    move_vel(0, a0, 0.8fx, EASE_LINEAR);
    spawn ecir_shoot();
    wait(120);
    move_vel(120, 270deg, 0.5fx, EASE_LINEAR);
    wait(120);
    move_vel(120, a2, 0.5fx, EASE_LINEAR);
    // src flagClear(12) re-enables offscreen recycling; the target engine recycles
    // by its own wider margin instead.
    loop { wait(1000); }
}

// src BossCard2_ECir00_at one shot: type8, speed 1.5, ANIM -4*velocity at spawn.
sub ecir_shot(color: int, spread: int) {
    var a: angle = aim_player();
    if spread != 0 {
        var rv: int = rand(65536);
        var signed_u: fx = ((rv-32768) as fx) / 32768;
        var off: int = (5461fx*signed_u) as int;
        a = a + (off as angle);
    }
    var px: fx = $self_x - 6fx*cos(a);
    var py: fx = $self_y - 6fx*sin(a);
    _ = fire(TH16_RICE, color, px, py, 1.5fx, a, none, none);
}

// src BossCard2_ECir00_at (1306-1337).
async sub ecir_shoot() {
    wait(10 + rand(30));
    for i in 0..9 {
        ecir_shot(2, 0);
        wait(30);
    }
    for j in 0..400 {
        ecir_shot(6, 1);
        wait(20);
    }
}

// src BossCard2 main body (1198-1262): the 120-frame shell buffer, then the
// +90 source label and the 1000-count loop; the 4200-frame interrupt cuts it
// after the partial 6th wave, which the segment budget reproduces, so the loop
// itself stays unbounded.
async sub boss_card() {
    wait(OPENING_BUFFER);
    wait(90);
    loop {
        spawn ecir_wave();
        card_wait(100);
        card_move_rand();
        card_wait(100);
        card_move_rand();
        card_wait(100);
        card_move_rand();
        card_wait(100);
        card_move_rand();
        card_wait(100);
        card_move_rand();
        card_wait(100);
        card_wait(90);
        card_wait(60);
        fire_back_ring();
        card_wait(40);
    }
}

// Entry state from st07bs Boss 31-41: 2000 hp, hurtbox 40, hitbox 48 at (0,128).
async sub boss_main() {
    set_invuln(65535);
    set_hurtbox(20fx);
    set_hitbox(24fx);
    spell_begin(0, SPELL_ID, boss_card, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 128fx, 2000, 0, 0, 0, boss_main);
    loop { wait(600); }
}
